import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertSame;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.anyString;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.*;

public class BeanDeserializerBase_deserializeFromDouble_TriageGen2Test {

    private JsonParser p;
    private DeserializationContext ctxt;
    private ValueInstantiator instantiator;
    private JsonDeserializer<Object> delegate;

    // We need a concrete subclass of BeanDeserializerBase to test the protected method
    private static class TestBeanDeserializer extends BeanDeserializerBase {
        protected TestBeanDeserializer(BeanDeserializerBuilder builder, BeanDescription beanDesc, BeanPropertyMap properties) {
            super(builder, beanDesc, properties, Collections.emptyMap(), Collections.emptySet(), false, false);
        }

        // Expose protected fields/methods for testing via reflection or by making them package-private in a real scenario.
        // Since we cannot change the source, we will use Mockito to mock the behavior of the base class 
        // or use a spy on a subclass.

        @Override
        public JsonDeserializer<Object> unwrappingDeserializer(com.fasterxml.jackson.databind.NameTransformer unwrapper) { return null; }
        @Override
        public BeanDeserializerBase withObjectIdReader(com.fasterxml.jackson.databind.ObjectIdReader oir) { return this; }
        @Override
        public BeanDeserializerBase withIgnorableProperties(java.util.Set<String> ignorableProps) { return this; }
        @Override
        public BeanPropertyMap withBeanProperties(BeanPropertyMap props) { return this; }
        @Override
        protected BeanDeserializerBase asArrayDeserializer() { return this; }
        @Override
        protected Object _deserializeUsingPropertyBased(JsonParser p, DeserializationContext ctxt) throws IOException { return null; }
    }

    // Because the fields _delegateDeserializer, _valueInstantiator, and _injectables are private in BeanDeserializerBase,
    // and the method is being tested, we must use a Mockito spy on a subclass and mock the internal calls 
    // if the fields were accessible, but since they are private, we must rely on a real instance 
    // and simulate the environment or use ReflectionTestUtils.

    // However, for a professional unit test where we can't change the source, 
    // we mock the dependencies that the method interacts with.

    private TestBeanDeserializer deserializer;

    @Before
    public void setup() throws Exception {
        p = mock(JsonParser.class);
        ctxt = mock(DeserializationContext.class);
        instantiator = mock(ValueInstantiator.class);
        delegate = mock(JsonDeserializer.class);

        // Since we cannot easily inject into private fields of BeanDeserializerBase via constructor,
        // we use reflection to set the private fields for the purpose of this test.
        deserializer = mock(TestBeanDeserializer.class, CALLS_REAL_METHODS);

        setField(deserializer, "_valueInstantiator", instantiator);
        setField(deserializer, "_delegateDeserializer", delegate);
        setField(deserializer, "_injectables", null);
    }

    private void setField(Object target, String fieldName, Object value) throws Exception {
        java.lang.reflect.Field field = BeanDeserializerBase.class.getDeclaredField(fieldName);
        field.setAccessible(true);
        field.set(target, value);
    }

    @Test
    public void testDeserializeFromDouble_IsDouble_CanCreateFromDouble() throws IOException {
        when(p.getNumberType()).thenReturn(NumberType.DOUBLE);
        when(p.getDoubleValue()).thenReturn(123.45);
        when(instantiator.canCreateFromDouble()).thenReturn(true);
        when(instantiator.createFromDouble(eq(ctxt), eq(123.45))).thenReturn("Success");

        Object result = deserializer.deserializeFromDouble(p, ctxt);

        assertEquals("Success", result);
        verify(instantiator).createFromDouble(ctxt, 123.45);
    }

    @Test
    public void testDeserializeFromDouble_IsFloat_CanCreateFromDouble() throws IOException {
        when(p.getNumberType()).thenReturn(NumberType.FLOAT);
        when(p.getDoubleValue()).thenReturn(1.23f);
        when(instantiator.canCreateFromDouble()).thenReturn(true);
        when(instantiator.createFromDouble(eq(ctxt), eq(1.23f))).thenReturn(1.23f);

        Object result = deserializer.deserializeFromDouble(p, ctxt);

        assertEquals(1.23f, (float)result, 0.001);
        verify(instantiator).createFromDouble(ctxt, 1.23f);
    }

    @Test
    public void testDeserializeFromDouble_IsDouble_CannotCreateFromDouble_UsesDelegate() throws IOException {
        when(p.getNumberType()).thenReturn(NumberType.DOUBLE);
        when(instantiator.canCreateFromDouble()).thenReturn(false);
        when(delegate.deserialize(p, ctxt)).thenReturn("DelegateObject");
        when(instantiator.createUsingDelegate(eq(ctxt), eq("DelegateObject"))).thenReturn("CreatedObject");

        // Mock injectValues (it's protected, so we need to be careful with the spy)
        doNothing().when(deserializer).injectValues(eq(ctxt), any());

        Object result = deserializer.deserializeFromDouble(p, ctxt);

        assertEquals("CreatedObject", result);
        verify(delegate).deserialize(p, ctxt);
        verify(instantiator).createUsingDelegate(ctxt, "DelegateObject");
    }

    @Test
    public void testDeserializeFromDouble_IsDouble_CannotCreateFromDouble_WithInjectables() throws IOException {
        when(p.getNumberType()).thenReturn(NumberType.DOUBLE);
        when(instantiator.canCreateFromDouble()).thenReturn(false);
        when(delegate.deserialize(p, ctxt)).thenReturn("DelegateObject");
        when(instantiator.createUsingDelegate(eq(ctxt), eq("DelegateObject"))).thenReturn("CreatedObject");

        setField(deserializer, "_injectables", new java.util.HashSet<>());

        Object result = deserializer.deserializeFromDouble(p, ctxt);

        assertEquals("CreatedObject", result);
        verify(deserializer).injectValues(eq(ctxt), eq("CreatedObject"));
    }

    @Test
    public void testDeserializeFromDouble_IsOtherType_HasDelegate() throws IOException {
        when(p.getNumberType()).thenReturn(NumberType.INTEGER);
        when(delegate.deserialize(p, ctxt)).thenReturn("DelegateObject");
        when(instantiator.createUsingDelegate(eq(ctxt), eq("DelegateObject"))).thenReturn("CreatedObject");

        Object result = deserializer.deserializeFromDouble(p, ctxt);

        assertEquals("CreatedObject", result);
        verify(delegate).deserialize(p, ctxt);
    }

    @Test
    public void testDeserializeFromDouble_IsOtherType_NoDelegate_HandleMissing() throws IOException {
        when(p.getNumberType()).thenReturn(NumberType.INTEGER);
        when(p.getNumberValue()).thenReturn(10);
        when(ctxt.handleMissingInstantiator(any(), eq(p), anyString(), eq(10L))).thenReturn("MissingObject");

        // Ensure _delegateDeserializer is null
        try { setField(deserializer, "_delegateDeserializer", null); } catch (Exception ignored) {}

        Object result = deserializer.deserializeFromDouble(p, ctxt);

        assertEquals("MissingObject", result);
        verify(ctxt).handleMissingInstantiator(any(), eq(p), anyString(), eq(10L));
    }
}
